public final class MainActivity extends Activity {
    static final int BG=Color.rgb(245,246,241),INK=Color.rgb(32,40,32),MUTED=Color.rgb(102,113,102),GREEN=Color.rgb(203,239,130),DARK=Color.rgb(38,60,41),SOFT=Color.rgb(236,244,228),WHITE=Color.WHITE;
    LinearLayout shell,content,nav;TextView progressText;ProgressBar progressBar;
    String page="home",exportPath="",exportName="",previousResult="";boolean previousBusy;
    final Handler handler=new Handler(Looper.getMainLooper());final ExecutorService io=Executors.newSingleThreadExecutor();
    List<AppEntry> apps=new ArrayList<>();Set<String> selected=new HashSet<>();
    static class AppEntry {String pkg,name;Drawable icon;AppEntry(String p,String n,Drawable d){pkg=p;name=n;icon=d;}}
    interface Checked {void run()throws Exception;}
    @Override public void onCreate(Bundle b){super.onCreate(b);selected=new HashSet<>(Vault.prefs(this).getStringSet("packages",new HashSet<>()));getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);previousResult=WorkState.resultDir;render("home");
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission("android.permission.POST_NOTIFICATIONS")!=PackageManager.PERMISSION_GRANTED&&!Vault.prefs(this).getBoolean("notification_asked",false)){Vault.prefs(this).edit().putBoolean("notification_asked",true).apply();requestPermissions(new String[]{"android.permission.POST_NOTIFICATIONS"},99);}
    }
    @Override protected void onResume(){super.onResume();if(Arrays.asList("home","records","restored").contains(page))render(page);previousBusy=WorkState.busy;handler.post(poll);}
    @Override protected void onPause(){handler.removeCallbacks(poll);super.onPause();}
    @Override protected void onDestroy(){io.shutdownNow();super.onDestroy();}
    final Runnable poll=new Runnable(){public void run(){if(progressText!=null){progressText.setText(WorkState.text.isEmpty()?"尚未开始备份":WorkState.text);progressBar.setProgress(WorkState.percent);progressBar.setVisibility(WorkState.busy?View.VISIBLE:View.GONE);}
        if(!WorkState.resultDir.equals(previousResult)){previousResult=WorkState.resultDir;if(!WorkState.busy&&!previousResult.isEmpty())render("restored");}
        else if(previousBusy&&!WorkState.busy&&Arrays.asList("home","records","restored").contains(page))render(page);
        previousBusy=WorkState.busy;handler.postDelayed(this,500);}};
    int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
    GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    TextView text(String s,int sp,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(color);t.setLineSpacing(dp(3),1);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return t;}
    void gap(LinearLayout p,int h){View v=new View(this);p.addView(v,new LinearLayout.LayoutParams(1,dp(h)));}
    LinearLayout card(int color){LinearLayout c=new LinearLayout(this);c.setOrientation(LinearLayout.VERTICAL);c.setPadding(dp(18),dp(18),dp(18),dp(18));c.setBackground(bg(color,22));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(14);content.addView(c,lp);return c;}
    TextView button(LinearLayout parent,String label,boolean primary,Checked action){TextView b=text(label,14,primary?WHITE:INK,true);b.setGravity(Gravity.CENTER);b.setPadding(dp(14),dp(12),dp(14),dp(12));b.setMinHeight(dp(52));b.setBackground(bg(primary?DARK:SOFT,17));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(8);parent.addView(b,lp);b.setOnClickListener(v->guard(action));b.setContentDescription(label);return b;}
    void guard(Checked action){try{action.run();}catch(Exception e){error(TransferService.clean(e));}}
    void error(String msg){if(!isFinishing())new AlertDialog.Builder(this).setTitle("暂时未完成").setMessage(msg).setPositiveButton("知道了",null).show();}
    void async(String label,Checked work,Runnable done){ProgressDialog dialog=new ProgressDialog(this);dialog.setMessage(label);dialog.setCancelable(false);dialog.show();io.execute(()->{try{work.run();handler.post(()->{if(!isFinishing()){dialog.dismiss();done.run();}});}catch(Exception e){handler.post(()->{if(!isFinishing()){dialog.dismiss();error(TransferService.clean(e));}});}});}
    EditText input(LinearLayout parent,String hint,boolean secret){EditText e=new EditText(this);e.setTextSize(15);e.setTextColor(INK);e.setSingleLine(true);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(bg(WHITE,14));e.setHint(hint);e.setInputType(secret?android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD:android.text.InputType.TYPE_CLASS_TEXT);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(10);parent.addView(e,lp);return e;}
    void title(String head,String sub){content.addView(text(head,28,INK,true));TextView t=text(sub,12,MUTED,false);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(6);lp.bottomMargin=dp(22);content.addView(t,lp);}
    void statusCard(){LinearLayout c=card(SOFT);progressText=text(WorkState.text.isEmpty()?"尚未开始备份":WorkState.text,12,INK,false);c.addView(progressText);progressBar=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progressBar.setMax(100);progressBar.setProgress(WorkState.percent);c.addView(progressBar);progressBar.setVisibility(WorkState.busy?View.VISIBLE:View.GONE);}
    void render(String target){page=target;progressText=null;progressBar=null;shell=new LinearLayout(this);shell.setOrientation(LinearLayout.VERTICAL);shell.setBackgroundColor(BG);setContentView(shell);
        shell.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(insets.getSystemWindowInsetLeft(),insets.getSystemWindowInsetTop(),insets.getSystemWindowInsetRight(),insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});shell.requestApplyInsets();
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);shell.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));content=new LinearLayout(this);content.setOrientation(LinearLayout.VERTICAL);content.setPadding(dp(22),dp(24),dp(22),dp(20));scroll.addView(content,new ScrollView.LayoutParams(-1,-2));
        switch(page){case"apps":showApps();break;case"records":showRecords();break;case"cloud":showCloud();break;case"settings":showSettings();break;case"restored":showRestored();break;default:showHome();}
        nav=new LinearLayout(this);nav.setOrientation(LinearLayout.HORIZONTAL);nav.setPadding(dp(10),dp(6),dp(10),dp(8));nav.setBackgroundColor(WHITE);shell.addView(nav,new LinearLayout.LayoutParams(-1,-2));
        String[]names={"备份","恢复","网盘","设置"},pages={"home","records","cloud","settings"};for(int i=0;i<4;i++){final String p=pages[i];TextView n=text(names[i],13,INK,page.equals(p)?true:false);n.setGravity(Gravity.CENTER);n.setPadding(dp(5),dp(15),dp(5),dp(15));if(page.equals(p)||i==0&&page.equals("apps")||i==1&&page.equals("restored"))n.setBackground(bg(GREEN,15));nav.addView(n,new LinearLayout.LayoutParams(0,-2,1));n.setOnClickListener(v->render(p));}
    }
    void showHome(){title("迁匣","把熟悉的一切，带到新手机");LinearLayout hero=card(GREEN);hero.addView(text("这台手机 · "+Build.MODEL,12,INK,false));gap(hero,18);hero.addView(text("先备份，再安心换机",23,INK,true));gap(hero,8);hero.addView(text("选好应用与数据文件，加密保存到网盘。\n新手机连接同一网盘，再下载恢复。",13,INK,false));gap(hero,12);button(hero,"选择要备份的内容",true,()->render("apps"));
        LinearLayout c=card(WHITE);c.addView(text("本次选择",16,INK,true));c.addView(text("已选 "+selected.size()+" 个应用 · "+documentCount()+" 份文件",12,MUTED,false));button(c,"开始加密备份",true,this::backupDialog);button(c,"添加应用导出的数据 / 其他文件",false,()->pickDocument(40,true));
        c=card(WHITE);c.addView(text("在新手机恢复",16,INK,true));button(c,"本地备份与导入",false,()->render("records"));button(c,"从我的网盘下载",false,()->render("cloud"));
        statusCard();c=card(SOFT);c.addView(text("普通模式的备份范围",14,INK,true));gap(c,5);c.addView(text("安装包（含拆分包）、你手动添加的文件。\n不包含其他应用的私有聊天记录、登录状态或内部数据库。",12,MUTED,false));
    }
    int documentCount(){try{return new JSONArray(Vault.prefs(this).getString("documents","[]")).length();}catch(Exception e){return 0;}}
    void showApps(){title("选择应用","仅备份你选择的内容 · 普通模式");EditText search=input(content,"搜索应用名称",false);gap(content,12);TextView count=text("已选择 "+selected.size()+" 个应用",13,INK,true);content.addView(count);LinearLayout list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);content.addView(list);gap(content,14);button(content,"管理已添加的数据文件",false,this::documentsDialog);button(content,"下一步：加密备份",true,this::backupDialog);
        Runnable fill=()->{list.removeAllViews();String q=search.getText().toString().toLowerCase(Locale.ROOT);for(AppEntry a:apps){if(!a.name.toLowerCase(Locale.ROOT).contains(q)&&!a.pkg.contains(q))continue;LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(12),dp(12),dp(12),dp(12));row.setBackground(bg(WHITE,18));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(10);list.addView(row,lp);ImageView icon=new ImageView(this);icon.setImageDrawable(a.icon);row.addView(icon,new LinearLayout.LayoutParams(dp(42),dp(42)));LinearLayout labels=new LinearLayout(this);labels.setOrientation(LinearLayout.VERTICAL);LinearLayout.LayoutParams ll=new LinearLayout.LayoutParams(0,-2,1);ll.leftMargin=dp(12);row.addView(labels,ll);labels.addView(text(a.name,15,INK,true));labels.addView(text("安装包 · 内部数据需应用主动导出",11,MUTED,false));CheckBox cb=new CheckBox(this);cb.setChecked(selected.contains(a.pkg));cb.setContentDescription("备份 "+a.name);row.addView(cb);cb.setOnCheckedChangeListener((v,on)->{if(on)selected.add(a.pkg);else selected.remove(a.pkg);Vault.prefs(this).edit().putStringSet("packages",new HashSet<>(selected)).apply();count.setText("已选择 "+selected.size()+" 个应用");});row.setOnClickListener(v->cb.setChecked(!cb.isChecked()));}};
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){fill.run();}public void afterTextChanged(Editable e){}});
        if(apps.isEmpty()){list.addView(text("正在读取应用列表…",13,MUTED,false));io.execute(()->{List<AppEntry>fresh=new ArrayList<>();for(ApplicationInfo a:getPackageManager().getInstalledApplications(0)){if((a.flags&ApplicationInfo.FLAG_SYSTEM)!=0||a.packageName.equals(getPackageName()))continue;fresh.add(new AppEntry(a.packageName,a.loadLabel(getPackageManager()).toString(),a.loadIcon(getPackageManager())));}Collections.sort(fresh,(a,b)->a.name.compareToIgnoreCase(b.name));handler.post(()->{apps=fresh;if(page.equals("apps"))fill.run();});});}else fill.run();
    }
    void backupDialog(){if(WorkState.busy){error("当前任务正在进行，请稍后");return;}if(selected.isEmpty()&&documentCount()==0){error("先选择应用，或添加数据文件");return;}
        LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(22),dp(8),dp(22),dp(10));form.addView(text("备份 "+selected.size()+" 个应用、"+documentCount()+" 份文件。\n请记住密码，新手机解密需要它。",13,INK,false));EditText pass=input(form,"恢复密码（至少8个字符）",true),again=input(form,"再次输入恢复密码",true);CheckBox cloud=new CheckBox(this);cloud.setText("生成后自动上传已连接的网盘");cloud.setChecked(!Vault.prefs(this).getString("dav_url","").isEmpty());form.addView(cloud);
        AlertDialog d=new AlertDialog.Builder(this).setTitle("加密并备份").setView(form).setPositiveButton("开始",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{String pw=pass.getText().toString();if(pw.length()<8||!pw.equals(again.getText().toString())){pass.setError("至少8个字符，两次密码要相同");return;}guard(()->{if(cloud.isChecked()&&Vault.prefs(this).getString("dav_url","").isEmpty())throw new IOException("请先连接网盘，或取消自动上传");TransferService.start(this,"backup",new Intent().putExtra("password",pw).putExtra("upload",cloud.isChecked()));d.dismiss();render("home");});}));d.show();
    }
    void documentsDialog()throws Exception{JSONArray docs=new JSONArray(Vault.prefs(this).getString("documents","[]"));String[]labels=new String[docs.length()+1];labels[0]="＋ 添加文件";for(int i=0;i<docs.length();i++)labels[i+1]=docs.getJSONObject(i).getString("name");new AlertDialog.Builder(this).setTitle("已添加的数据文件").setItems(labels,(d,index)->{if(index==0){pickDocument(40,true);return;}new AlertDialog.Builder(this).setMessage("从备份选择中移除此文件？原文件不会删除。").setPositiveButton("移除",(v,w)->guard(()->{docs.remove(index-1);Vault.prefs(this).edit().putString("documents",docs.toString()).apply();render(page);})).setNegativeButton("取消",null).show();}).setNegativeButton("关闭",null).show();}
    void pickDocument(int code,boolean multiple){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);if(multiple)i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,code);}
    void showRecords(){title("本地备份与恢复","也可从网盘下载备份包，再在这里导入");button(content,"导入备份包 .qxb",true,()->pickDocument(60,false));if(!WorkState.resultDir.isEmpty())button(content,"查看最近解密的应用和数据",false,()->render("restored"));gap(content,18);statusCard();
        File[]files=BackupEngine.backups(this).listFiles(f->f.getName().endsWith(".qxb"));if(files==null||files.length==0){LinearLayout c=card(WHITE);c.addView(text("还没有本地备份",16,INK,true));c.addView(text("旧手机先备份；新手机先下载或导入。",12,MUTED,false));return;}Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));
        for(File f:files){LinearLayout c=card(WHITE);c.addView(text(f.getName(),14,INK,true));String sub=size(f.length());try{JSONObject r=BackupEngine.readJson(new File(f.getPath()+".json"));sub+=" · "+r.optString("status","待恢复");}catch(Exception ignored){}c.addView(text(sub,12,MUTED,false));button(c,"输入密码并解密恢复",true,()->restoreDialog(f));button(c,"上传 / 导出 / 分享",false,()->recordActions(f));}
    }
    void restoreDialog(File f){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(22),dp(8),dp(22),dp(10));form.addView(text("先验证与解密，不会自动覆盖其他应用的数据。",13,INK,false));EditText pass=input(form,"输入备份时设置的密码",true);AlertDialog d=new AlertDialog.Builder(this).setTitle("解密备份").setView(form).setPositiveButton("解密",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->guard(()->{if(pass.getText().length()<8){pass.setError("请输入恢复密码");return;}TransferService.start(this,"restore",new Intent().putExtra("path",f.getAbsolutePath()).putExtra("password",pass.getText().toString()));d.dismiss();})));d.show();}
    void recordActions(File f){new AlertDialog.Builder(this).setTitle("备份文件操作").setItems(new String[]{"上传到已连接的网盘","另存到手机 / 网盘目录","分享给网盘 App","删除本地副本"},(v,index)->guard(()->{if(index==0)TransferService.start(this,"upload",new Intent().putExtra("path",f.getAbsolutePath()));else if(index==1)export(f,f.getName());else if(index==2)share(f);else new AlertDialog.Builder(this).setTitle("删除本地副本？").setMessage("不会删除网盘文件。请先确认另一份备份已经可用。").setPositiveButton("删除",(d,w)->guard(()->{if(WorkState.busy)throw new IOException("任务进行中，稍后再删除");f.delete();new File(f.getPath()+".json").delete();render("records");})).setNegativeButton("取消",null).show();})).show();}
    void share(File f)throws Exception{Uri u=ShareProvider.uri(this,f);Intent i=new Intent(Intent.ACTION_SEND).setType("application/octet-stream").putExtra(Intent.EXTRA_STREAM,u).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);i.setClipData(ClipData.newRawUri("迁匣备份",u));startActivity(Intent.createChooser(i,"保存到网盘或发送到新手机"));}
    void export(File f,String name){exportPath=f.getAbsolutePath();exportName=name.replace('/','_').replace('\\','_');Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("application/octet-stream").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,exportName);startActivityForResult(i,70);}
    void showCloud(){title("我的网盘","连接后，备份可自动上传；新机可独立下载");statusCard();LinearLayout c=card(SOFT);c.addView(text("WebDAV 连接",16,INK,true));c.addView(text("填写网盘提供的、已经存在的目录地址。\n坚果云通常需要生成应用密码。",12,MUTED,false));EditText url=input(c,"https://你的网盘地址/dav/目录/",false);url.setText(Vault.prefs(this).getString("dav_url",""));url.setInputType(android.text.InputType.TYPE_CLASS_TEXT|android.text.InputType.TYPE_TEXT_VARIATION_URI);EditText user=input(c,"账号",false);user.setText(Vault.prefs(this).getString("dav_user",""));EditText secret=input(c,"应用密码（留空使用已保存密码）",true);CheckBox http=new CheckBox(this);http.setText("允许 HTTP（账号会明文传输）");http.setChecked(Vault.prefs(this).getBoolean("allow_http",false));c.addView(http);
        button(c,"测试连接并保存",true,()->{String address=url.getText().toString().trim(),username=user.getText().toString().trim(),pw=secret.getText().toString();boolean allow=http.isChecked();async("检查网盘读写权限…",()->{String pass=pw.isEmpty()?Vault.get(this,"dav_secret"):pw;DavClient dav=new DavClient(address,username,pass,allow);dav.test();Vault.put(this,"dav_secret",pass);Vault.prefs(this).edit().putString("dav_url",address).putString("dav_user",username).putBoolean("allow_http",allow).commit();},()->{Toast.makeText(this,"连接成功，读写校验通过",Toast.LENGTH_LONG).show();render("cloud");});});
        button(content,"读取网盘备份列表",true,this::cloudList);button(content,"没有接口的网盘：手动上传 / 导入",false,()->new AlertDialog.Builder(this).setTitle("使用其他网盘").setMessage("旧手机生成本地备份后，在备份记录里点“分享给网盘 App”。\n新手机用网盘 App 下载 .qxb，再在迁匣的恢复页导入。\n百度网盘、阿里云盘等尚未直接接入官方接口。").setPositiveButton("知道了",null).show());
    }
    void cloudList(){final List<DavClient.Item>items=new ArrayList<>();async("正在读取网盘备份…",()->items.addAll(Vault.dav(this).list()),()->{if(items.isEmpty()){error("这个目录还没有 .qxb 备份。请确认新旧手机填写同一目录。");return;}String[]labels=new String[items.size()];for(int i=0;i<labels.length;i++)labels[i]=items.get(i).name+"\n"+size(items.get(i).size);new AlertDialog.Builder(this).setTitle("网盘中的备份").setItems(labels,(d,n)->guard(()->{String name=items.get(n).name;if(new File(BackupEngine.backups(this),name).exists()){render("records");Toast.makeText(this,"本地已有这份备份",Toast.LENGTH_LONG).show();return;}TransferService.start(this,"download",new Intent().putExtra("name",name));render("records");})).setNegativeButton("关闭",null).show();});}
    void showSettings(){title("设置","选择一次，后续可自动备份");LinearLayout c=card(WHITE);c.addView(text("自动备份",17,INK,true));c.addView(text(Vault.prefs(this).getBoolean("auto_enabled",false)?"已开启 · 每24小时 · Wi-Fi且充电":"尚未开启",13,MUTED,false));gap(c,8);c.addView(text("时间由系统调度，可能延后。使用你当前选择的应用与文件；导出文件更新后才能备份新内容。",12,MUTED,false));button(c,"设置密码并开启",true,this::autoDialog);button(c,"关闭自动备份",false,()->{BackupJob.disable(this);render("settings");});
        c=card(SOFT);c.addView(text("内部数据与 Root",16,INK,true));gap(c,6);c.addView(text("本版支持安装包和你主动选择的文件。其他应用的私有聊天记录、数据库和登录状态不能直接读取；尚未实现 Root 内部数据备份恢复。",12,MUTED,false));
        c=card(WHITE);c.addView(text("迁匣 1.0.0",16,INK,true));c.addView(text("AES-256-GCM 分块加密\n恢复密码可在新手机使用，网盘凭证保存在本机。",12,MUTED,false));button(c,"允许安装恢复的应用",false,()->startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName()))));button(c,"清理解密缓存",false,()->new AlertDialog.Builder(this).setMessage("清除已解密的安装包与数据文件？原加密备份不会删除。").setPositiveButton("清除",(d,w)->guard(()->{if(WorkState.busy)throw new IOException("当前有任务进行中");FileOps.delete(BackupEngine.restores(this));WorkState.resultDir="";Vault.prefs(this).edit().putString("restore_dir","").apply();render("settings");})).setNegativeButton("取消",null).show());
    }
    void autoDialog(){LinearLayout form=new LinearLayout(this);form.setOrientation(LinearLayout.VERTICAL);form.setPadding(dp(22),dp(8),dp(22),dp(10));form.addView(text("开启后，恢复密码会加密保存在本机，供后台备份使用。你仍需记住密码用于新机恢复。",13,INK,false));EditText p=input(form,"设置恢复密码（至少8位）",true),p2=input(form,"再次输入密码",true);AlertDialog d=new AlertDialog.Builder(this).setTitle("开启自动备份").setView(form).setPositiveButton("开启",null).setNegativeButton("取消",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->guard(()->{String pw=p.getText().toString();if(pw.length()<8||!pw.equals(p2.getText().toString())){p.setError("两次密码必须相同，至少8位");return;}if(Vault.prefs(this).getString("dav_url","").isEmpty())throw new IOException("请先连接网盘");if(selected.isEmpty()&&documentCount()==0)throw new IOException("先选择备份内容");async("保存自动备份计划…",()->{Vault.put(this,"auto_password",pw);BackupJob.enable(this);},()->{d.dismiss();render("settings");});})));d.show();}
    void showRestored(){title("解密后的内容","安装与数据导入分别完成，结果分别记录");statusCard();try{File dir=new File(WorkState.resultDir);if(!dir.getCanonicalPath().startsWith(BackupEngine.restores(this).getCanonicalPath()+"/"))throw new IOException("没有可用的解密结果");JSONObject m=BackupEngine.readJson(new File(dir,"manifest.json"));JSONArray appList=m.getJSONArray("apps"),files=m.getJSONArray("files");JSONObject states=new File(dir,"installation.json").exists()?BackupEngine.readJson(new File(dir,"installation.json")):new JSONObject();
        LinearLayout c=card(GREEN);c.addView(text(appList.length()+" 个应用 · "+m.getString("device"),18,INK,true));c.addView(text("完整性校验通过。数据文件需要在对应应用中导入；此备份不包含应用私有数据。",12,INK,false));
        for(int i=0;i<appList.length();i++){JSONObject a=appList.getJSONObject(i);c=card(WHITE);c.addView(text(a.getString("name"),16,INK,true));c.addView(text("版本 "+a.optString("version")+" · "+states.optString(a.getString("package"),"待安装"),12,MUTED,false));button(c,"安装应用（系统会要求确认）",true,()->{if(!getPackageManager().canRequestPackageInstalls()){startActivity(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())));return;}new AlertDialog.Builder(this).setTitle("安装 "+a.getString("name")+"？").setMessage("如手机已有该应用，系统会检查签名和版本，可能拒绝更新。请确认后继续。不会自动导入数据文件。").setPositiveButton("安装",(d,w)->async("准备安装包…",()->Installer.install(this,dir,a),()->Toast.makeText(this,"请完成系统安装确认",Toast.LENGTH_LONG).show())).setNegativeButton("取消",null).show();});}
        for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(!f.getString("kind").equals("export"))continue;File local=new File(dir,f.getString("path"));c=card(WHITE);c.addView(text(f.getString("name"),15,INK,true));c.addView(text(size(f.getLong("bytes"))+" · 等待你在原应用中导入",12,MUTED,false));button(c,"保存数据文件",false,()->export(local,f.getString("name")));}
        }catch(Exception e){LinearLayout c=card(WHITE);c.addView(text("尚未解密备份",16,INK,true));button(c,"返回备份列表",true,()->render("records"));}}
    public static String size(long bytes){if(bytes<0)return "容量未知";if(bytes>=1024L*1024*1024)return String.format(Locale.CHINA,"%.2f GB",bytes/(1024.0*1024*1024));if(bytes>=1024*1024)return String.format(Locale.CHINA,"%.1f MB",bytes/(1024.0*1024));return String.format(Locale.CHINA,"%.1f KB",bytes/1024.0);}
    String fileName(Uri uri){String name=null;try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())name=c.getString(0);}catch(Exception ignored){}return name==null?"数据文件":name;}
    @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null)return;guard(()->{
        if(request==40){JSONArray docs=new JSONArray(Vault.prefs(this).getString("documents","[]"));List<Uri> uris=new ArrayList<>();if(data.getClipData()!=null)for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());else if(data.getData()!=null)uris.add(data.getData());for(Uri u:uris){try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);}catch(SecurityException e){throw new IOException("此文件来源不支持持续授权，请先保存到手机再添加");}boolean duplicate=false;for(int i=0;i<docs.length();i++)if(docs.getJSONObject(i).getString("uri").equals(u.toString()))duplicate=true;if(!duplicate)docs.put(new JSONObject().put("uri",u.toString()).put("name",fileName(u)).put("package",selected.size()==1?selected.iterator().next():""));}Vault.prefs(this).edit().putString("documents",docs.toString()).apply();render(page);Toast.makeText(this,"文件已加入备份选择",Toast.LENGTH_LONG).show();}
        else if(request==60&&data.getData()!=null){TransferService.start(this,"import",new Intent().putExtra("uri",data.getData().toString()));render("records");}
        else if(request==70&&data.getData()!=null&&!exportPath.isEmpty()){TransferService.start(this,"export",new Intent().putExtra("path",exportPath).putExtra("uri",data.getData().toString()));}
    });}
    @Override public void onBackPressed(){if(!page.equals("home"))render("home");else super.onBackPressed();}
}
